// Declaración moderna de variables
const limiteMaximo = 100;
let contadorActual = 0;

// Función clásica vs Función Flecha
const sumarClasica = function(a, b) {
    return a + b;
};

// Función flecha con retorno implícito
const sumarModerna = (a, b) => a + b;

console.log(sumarModerna(5, 10)); // Imprime 15

// Consumo de API usando async/await y fetch con manejo de errores
async function obtenerUsuario(id) {
  try {
    const respuesta = await fetch(`https://jsonplaceholder.typicode.com/users/${id}`);
    if (!respuesta.ok) {
      throw new Error('No se pudo conectar con el servidor');
    }
    const datosUsuario = await respuesta.json();
    console.log(`Usuario: ${datosUsuario.name}`);
  } catch (error) {
    console.error('Ocurrió un error:', error.message);
  }
}

obtenerUsuario(1);

ejercicio_practico.solucion_paso_a_paso:
Paso 1: Define la función precedida por la palabra clave 'async'.
Paso 2: Implementa la estructura try/catch.
Paso 3: Realiza la llamada a fetch usando 'await'.
Paso 4: Convierte la respuesta a JSON usando 'await respuesta.json()'.
Paso 5: Retorna la propiedad 'title' del objeto resultante.

Código de solución:
async function obtenerPost(id) {
  try {
    const res = await fetch(`https://jsonplaceholder.typicode.com/posts/${id}`);
    const post = await res.json();
    return post.title;
  } catch (error) {
    console.log('Error:', error);
  }
}
